const arts='assets/';
const iconPaths={closet:'M2 9l6-5 4 2 4-2 6 5-4 4-2-2v10H8V11l-2 2z',zip:'M7 2v20m10-20v20M7 4h5m0 3h5M7 10h5m0 3h5M7 16h5m0 3h5',hair:'M6 21c-4-11 3-21 10-17 5 3-1 10 4 15m-9 2C7 13 19 9 14 5m1 15c-2-4 2-6 2-10',fit:'M3 8l16-4 3 11-16 5zM7 7l1 4m3-5 1 3m3-4 1 4',box:'M3 7l9-5 9 5v11l-9 5-9-5zM3 7l9 5 9-5m-9 5v11M7 5l10 5',return:'M9 4L3 10l6 6M4 10h11a6 6 0 010 12',mail:'M2 5h20v14H2zM2 5l10 8L22 5',star:'M12 1c0 7-4 10-10 11 7 1 9 4 10 11 1-7 4-10 10-11-6-1-10-4-10-11z',bag:'M3 7h18l-1 14H4zM8 8V6a4 4 0 0 1 8 0v2'};
const ico=(id)=>`<svg class="lineicon" aria-hidden="true" viewBox="0 0 24 24"><path d="${iconPaths[id]||iconPaths.star}"/></svg>`;
const img=(src,alt,cls='')=>`<img class="${cls}" src="${src}" alt="${alt}" loading="lazy">`;
const over=t=>`<div class="over">${ico('star')}${t}</div>`;
const cta=(r,t)=>`<a class="pill" href="#${r}">${t}</a>`;
const hh=()=>window.hhShop;
const shelf=[['top','Second Skin Collection','Onyx','Mocha'],['bodysuit','Second Skin Collection','Onyx','Mocha'],['zip','Shapewear','Brown','Black'],['plunge','Shapewear','Brown'],['bob','Hair']];
const cardPhoto={top:'ss-top-onyx-1',bodysuit:'editor-long',zip:'editor-zip',plunge:'editor-plunge'};
const colourPhoto={top:{Onyx:'ss-top-onyx-1',Mocha:'ss-top-mocha-1'},bodysuit:{Onyx:'editor-long',Mocha:'long-brown'},zip:{Black:'zip-black',Brown:'zip'},plunge:{Brown:'plunge'}};
const swatchHex=c=>(c==='Black'||c==='Onyx')?'#211c1a':'#64412e';
const cards=()=>shelf.map(([id,g,...cols])=>{const p=hh().products[id],n=p.name,src=id==='bob'?'hair.webp':arts+cardPhoto[id]+'.webp',colourSel=cols.length?'?colour='+cols[0]:'';return `<article class="piece" data-piece="${id}"><a class="piecephoto" href="#product/${id}${colourSel}">${img(src,n)}<span>${g}</span></a><div class="pieceinfo"><a href="#product/${id}${colourSel}">${n}</a><p class="price">${hh().price(p.price)}</p>${cols.length>1?`<div class="swatches">${cols.map((c,i)=>`<button style="--sw:${swatchHex(c)}" type="button" data-swatch="${c}" aria-label="${n}, ${c}" aria-pressed="${i===0}"></button>`).join('')}</div>`:''}</div></article>`}).join('');
const support=[['fit','Size & fit','closet'],['bag','Secure checkout','cart'],['box','Delivery','shipping'],['return','Returns','returns']];
const spark=words=>{const g='<div>'+words.map(w=>'<span>'+w+'</span><i aria-hidden="true">✦</i>').join('')+'</div>';return '<div class="ribbon spark" aria-hidden="true"><div class="ribbon-belt">'+g+g+g+g+'</div></div>'};
function homepage(){return `<section class="campaign"><img class="campaign-photo" fetchpriority="high" src="assets/hero-fabric-provided.png" alt="Chocolate-brown fabric texture"><img class="hero-composition" src="assets/hero-model-provided.png" alt="HoneyHaus model in chocolate-brown shapewear with golden arch and flowers"><div class="campaign-type"><div class="hero-kicker"><span></span>H O N E Y H A U S<span></span></div><h1>Where comfort meets <em>confidence.</em></h1><p class="manifesto">Everyday layers. Signature hair.</p><div class="campaign-actions">${cta('closet','Shop Closet')}<span class="hero-arrow">→</span>${cta('hair','Shop Hair')}</div></div></section>
<section class="discnav" aria-label="Shop by category">${[['ss-top-mocha-1','Second Skin','Elevate','secondskin'],['zip-macro','Shapewear','Sculpt','shapewear'],['atelier-4','Ready-to-wear wigs','Style','hair'],['fabric','Shop all','Explore','shop']].map(([f,n,sub,r])=>`<a href="#${r}">${img(arts+f+'.webp','')}<strong>${n}</strong><small>${sub}</small></a>`).join('')}</section>
${spark(['HoneyHaus Closet','Elevated Basics','Sculpting Essentials','HoneyHaus Hair','Ready-to-Wear Wigs'])}
<section class="story-grid content"><div><small>THE SECOND SKIN COLLECTION</small><h2>Elevated Basics.</h2><p>Your everyday essentials, redefined. Designed to embrace your curves, complement your silhouette and elevate your everyday wardrobe.</p>${cta('secondskin','Shop Second Skin')}</div>${img(arts+'ss-top-mocha-2.webp','Second Skin Long Sleeve Top in Mocha, styled with cream trousers')}${img('hair.webp','HoneyHaus Hair editorial portrait')}<div><h2>The Hair Edit</h2><p>Luxury ready-to-wear wigs designed for effortless styling and everyday confidence. Quality &amp; beautiful hair, without the fuss.</p>${cta('hair','Shop HoneyHaus Hair')}</div></section>
<section class="edit-grid content"><div class="edit-title"><div><small>THE HONEYHAUS EDIT</small><h2>Your everyday essentials, elevated.</h2></div><a class="under" href="#shop">Shop All</a></div><div class="products-four">${cards()}</div></section>
<section class="feature-band"><div><small>THE FINER DETAILS</small><h2>Designed with you in mind.</h2><p>Thoughtfully designed essentials that embrace your curves and elevate your everyday wardrobe.</p>${cta("shapewear","Shop Shapewear")}</div><figure class="ken">${[1,2,3,4].map(i=>img(arts+"detail-"+i+".webp","Garment detail "+i)).join("")}<button data-motion aria-pressed="false">Pause motion</button></figure><div>${[['Double-layered fabric','A smooth, comfortable second-skin feel.','zip'],['Dual hook-and-zip closure','Designed for enhanced compression, a snatched waist and a smooth, seamless finish under your clothes.','zip'],['Adjustable straps','A more personalised fit.','plunge']].map(([q,a,r],i)=>`<details name="features" ${i?'':'open'}><summary>${ico(["fit","zip","fit"][i])}${q}</summary><p>${a} <a class="under" href="#product/${r}">View piece</a></p></details>`).join('')}</div></section>
<section class="doors">${[['ss-top-mocha-1','HoneyHaus Closet','Elevated essentials. Everyday confidence.','Shop Closet','closet'],['hair','HoneyHaus Hair','Luxury hair. Ready-To-Wear Wigs.','Shop Hair','hair']].map(([f,t,tag,b,r])=>`<a href="#${r}">${img(f==='hair'?'hair.webp':arts+f+'.webp','')}<div><h2>${t}</h2><p>${tag}</p><span>${b}</span></div></a>`).join('')}</section>
<div class="services">${support.map(([i,t,r])=>`<a href="#${r}">${ico(i)}<span>${t}</span></a>`).join('')}</div>
<section class="pairing content">${img(arts+'ss-top-onyx-1.webp','Second Skin Long Sleeve Top in Onyx, styled with jeans')}<div><small>SHOP THE LOOK</small><h2>Recreate the look.</h2><a href="#product/top?colour=Onyx">${img(arts+'ss-top-onyx-flat.webp','Second Skin Long Sleeve Top in Onyx')}<strong>Second Skin Long Sleeve Top</strong><span class="under">View piece</span></a></div></section>
${floatingStory()}${world()}`;}
function renderRoute(){const route=location.hash.slice(1)||'home';document.body.classList.toggle('on-home',route==='home');document.querySelector('header').classList.remove('open');document.getElementById('menub').setAttribute('aria-expanded','false');if(route==='home'){document.getElementById('app').innerHTML=homepage();document.title='HoneyHaus — Closet & Hair';document.querySelector('meta[name=description]').content='Discover ready-to-wear wigs, sculpting shapewear and elevated everyday essentials.'}else window.shopRender(route);window.scrollTo({top:0,behavior:"instant"});syncMast()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-swatch]');if(!b)return;const item=b.closest('.piece'),id=item.dataset.piece,c=b.dataset.swatch;item.querySelector('img').src=arts+colourPhoto[id][c]+'.webp';item.querySelectorAll('a').forEach(a=>a.href='#product/'+id+'?colour='+c);item.querySelectorAll('[data-swatch]').forEach(el=>el.setAttribute('aria-pressed',el===b))});
document.getElementById('menub').onclick=e=>e.currentTarget.setAttribute('aria-expanded',document.querySelector('header').classList.toggle('open'));window.addEventListener('hashchange',renderRoute);renderRoute();
const revealObserver = new IntersectionObserver(entries => entries.forEach(entry => {
 if(entry.isIntersecting){entry.target.classList.add('arriving');revealObserver.unobserve(entry.target)}
}), {threshold:.08});
function observeSections(){revealObserver.disconnect();document.querySelectorAll('#app>section:not(:first-child)').forEach(el=>revealObserver.observe(el))}
observeSections();window.addEventListener('hashchange',observeSections);
const footerMarkup='<div class="foot-benefits"><div class="foot-benefit">'+ico('closet')+'<b>ELEVATED BASICS</b><span>The Second Skin Collection</span></div><div class="foot-benefit">'+ico('zip')+'<b>SCULPTING SHAPEWEAR</b><span>Designed to embrace your curves</span></div><div class="foot-benefit">'+ico('hair')+'<b>READY-TO-WEAR WIGS</b><span>Luxury hair, without the fuss</span></div><div class="foot-benefit">'+ico('return')+'<b>HELP WHEN YOU NEED IT</b><span>Simple care and returns</span></div></div><div class="foot-intro"><small>HONEYHAUS</small><button data-up aria-label="Back to top">↑</button></div><div class="foot"><div><b>SHOP</b><a href="#shop">All products</a><a href="#secondskin">Second Skin</a><a href="#shapewear">Shapewear</a><a href="#hair">Ready-to-wear wigs</a></div><div><b>EXPLORE</b><a href="#about">Our Haus</a><a href="#faq">FAQs</a><a href="#shipping">Delivery</a><a href="#contact">Contact</a></div><div><b>CUSTOMER CARE</b><a href="#account">My account</a><a href="#cart">Your bag</a><a href="#returns">Returns &amp; refunds</a><a href="#privacy">Privacy policy</a></div><div class="foot-news"><h3>A little luxury in your inbox.</h3><p>Discover new drops, styling notes and moments of inspiration.</p><form onsubmit="return false"><input type="email" placeholder="Your email address" aria-label="Your email address"><button>JOIN THE LIST</button></form></div></div><img class="footer-wordmark" src="assets/footer-wordmark-brown.png" alt="HoneyHaus"><small>© HoneyHaus &nbsp; · &nbsp; United Kingdom · GBP £</small>';
document.querySelector('footer').innerHTML=footerMarkup;const refinements=document.createElement('link');refinements.rel='stylesheet';refinements.href='overrides.css';document.head.appendChild(refinements);const heroStyles=document.createElement('link');heroStyles.rel='stylesheet';heroStyles.href='hero-overrides.css';document.head.appendChild(heroStyles);const amend=document.createElement('link');amend.rel='stylesheet';amend.href='amend.css';document.head.appendChild(amend);
